                if (player.secret_achievements.secretnumber.eq(114514)) dis = "homo"
                if (player.secret_achievements.secretnumber.eq(1919810)) dis = "臭死力"
                if (player.secret_achievements.secretnumber.eq(74751)) dis = "嬲"
                if (player.secret_achievements.secretnumber.eq(501761)) dis = "乌鸦喝水，爱你呦！"
                if (player.secret_achievements.secretnumber.gte("1e1000")) dis = "你还在这里吗？"
                if (player.secret_achievements.secretnumber.gte("1e10000")) dis = "认真的？"
                if (player.secret_achievements.secretnumber.gte("1e100000")) dis = "不可思议"
                if (player.secret_achievements.secretnumber.gte("1e1000000")) dis = "你用连点器在这挂机几小时？"
