function resetPzE() {
    if (hasUpgrade('puzzle', 44)) return;
    player.puzzle.energy = d(0),
        player.puzzle.points = d(0),
        resetonoff()
}

function resetonoff() {
    player.puzzle.on = d(0),
        player.puzzle.off = d(0)
}

